import { useEffect, useState } from "react";
import axios from "axios";

import Login from "./components/Login";
import AdminPanel from "./components/AdminPanel";

const API_URL = "http://localhost:5000";

function App() {
  // =======================
  // STATE
  // =======================
  const [candidates, setCandidates] = useState([]);
  const [darkMode, setDarkMode] = useState(false);
  const [auth, setAuth] = useState({
    token: localStorage.getItem("token") || null,
    role: localStorage.getItem("role") || null,
  });
  const [loginForm, setLoginForm] = useState({ email: "", password: "" });
  const [candidateForm, setCandidateForm] = useState({
    firstName: "",
    lastName: "",
    candidacy: "",
    description: "",
    image: null,
  });
  const [editId, setEditId] = useState(null);
  const [message, setMessage] = useState("");

  // =======================
  // FETCH CANDIDATES
  // =======================
  const fetchCandidates = async () => {
    try {
      const res = await axios.get(`${API_URL}/api/candidates`);
      setCandidates(res.data);
    } catch (error) {
      console.error(error);
      setMessage("Failed to load candidates.");
    }
  };

  useEffect(() => {
    fetchCandidates();
  }, []);

  // =======================
  // LOGIN / LOGOUT
  // =======================
  const handleLogin = async () => {
    try {
      const res = await axios.post(`${API_URL}/api/auth/login`, loginForm);
      localStorage.setItem("token", res.data.token);
      localStorage.setItem("role", res.data.role);
      setAuth({ token: res.data.token, role: res.data.role });
      setMessage("Login successful.");
    } catch (error) {
      console.error(error);
      setMessage("Invalid email or password.");
    }
  };

  const handleLogout = () => {
    localStorage.removeItem("token");
    localStorage.removeItem("role");
    setAuth({ token: null, role: null });
    setMessage("Logged out successfully.");
  };

  // =======================
  // VOTE
  // ======================= 
    const handleVote = async (id, position) => {
    try {
    const res = await axios.post(
      `${API_URL}/api/vote/${id}`,
      {},
      { headers: { Authorization: `Bearer ${auth.token}` } }
    );
    setMessage(res.data.message);

    // Save the position as voted
    setVotedPositions((prev) => [...prev, position]);

    fetchCandidates();
  } catch (error) {
    console.error(error);
    setMessage(error.response?.data?.message || "An error occurred while voting.");
  }
};


  // =======================
  // ADD / EDIT CANDIDATE
  // =======================
  const handleSaveCandidate = async () => {
    try {
      const formData = new FormData();
      formData.append("firstName", candidateForm.firstName);
      formData.append("lastName", candidateForm.lastName);
      formData.append("candidacy", candidateForm.candidacy);
      formData.append("description", candidateForm.description || "");
      if (candidateForm.image) formData.append("image", candidateForm.image);

      if (editId) {
        await axios.put(`${API_URL}/api/candidates/${editId}`, formData, {
          headers: { Authorization: `Bearer ${auth.token}` },
        });
        setMessage("Candidate updated successfully.");
      } else {
        await axios.post(`${API_URL}/api/candidates`, formData, {
          headers: { Authorization: `Bearer ${auth.token}` },
        });
        setMessage("Candidate added successfully.");
      }

      setCandidateForm({
        firstName: "",
        lastName: "",
        candidacy: "",
        description: "",
        image: null,
      });
      setEditId(null);
      fetchCandidates();
    } catch (error) {
      console.error(error);
      setMessage("Failed to save candidate.");
    }
  };

  // =======================
  // DELETE CANDIDATE
  // =======================
  const handleDeleteCandidate = async (id) => {
    try {
      await axios.delete(`${API_URL}/api/candidates/${id}`, {
        headers: { Authorization: `Bearer ${auth.token}` },
      });
      setMessage("Candidate deleted.");
      fetchCandidates();
    } catch (error) {
      console.error(error);
      setMessage("Failed to delete candidate.");
    }
  };

  // =======================
  // GROUP CANDIDATES BY POSITION
  // =======================
  const groupedCandidates = candidates.reduce((acc, candidate) => {
    const key = candidate.candidacy || "Other";
    if (!acc[key]) acc[key] = [];
    acc[key].push(candidate);
    return acc;
  }, {});

  // =======================
  // THEME
  // =======================
  const theme = {
    background: darkMode ? "#49494b" : "#b7a8a8",
    text: darkMode ? "#e5e7eb" : "#000000",
    card: darkMode ? "#020617" : "#ffffff",
    border: "#1e40af",
    button: "#1e40af",
  };

  // =======================
  // UI
  // =======================
  return (
    <div
      style={{
        minHeight: "100vh",
        width: "100%",
        padding: 20,
        backgroundColor: theme.background,
        color: theme.text,
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        boxSizing: "border-box",
      }}
    >
      <h1 style={{ textAlign: "center", marginBottom: 15 }}>
        Online Voting System
      </h1>

      {/* Dark Mode / Logout */}
      <div style={{ display: "flex", marginBottom: 15 }}>
        <button
          onClick={() => setDarkMode(!darkMode)}
          style={{
            backgroundColor: theme.button,
            color: "white",
            border: "none",
            padding: "6px 12px",
            borderRadius: 6,
            cursor: "pointer",
            marginRight: auth.token ? 10 : 0,
          }}
        >
          {darkMode ? "☀ Light Mode" : "🌙 Dark Mode"}
        </button>

        {auth.token && (
          <button
            onClick={handleLogout}
            style={{
              backgroundColor: theme.button,
              color: "white",
              border: "none",
              padding: "6px 12px",
              borderRadius: 6,
              cursor: "pointer",
            }}
          >
            Logout
          </button>
        )}
      </div>

      {message && <p>{message}</p>}

      {/* Login Form */}
      {!auth.token && (
        <div
          style={{
            border: `2px solid ${theme.border}`,
            padding: 15,
            borderRadius: 8,
            marginBottom: 20,
            backgroundColor: theme.card,
            width: "100%",
            maxWidth: 400,
          }}
        >
          <Login
            loginForm={loginForm}
            setLoginForm={setLoginForm}
            onLogin={handleLogin}
          />
        </div>
      )}

      {/* Admin Panel */}
      {auth.token && auth.role === "admin" && (
        <div
          style={{
            border: `2px solid ${theme.border}`,
            padding: 15,
            borderRadius: 8,
            marginBottom: 20,
            backgroundColor: theme.card,
            width: "100%",
            maxWidth: 500,
          }}
        >
          <AdminPanel
            candidateForm={candidateForm}
            setCandidateForm={setCandidateForm}
            onSave={handleSaveCandidate}
          />
        </div>
      )}

      {/* Candidates Section */}
      <section style={{ width: "100%", maxWidth: 600 }}>
        <h2>Candidates</h2>
        {Object.keys(groupedCandidates).length === 0 ? (
          <p>No candidates found.</p>
        ) : (
          Object.entries(groupedCandidates).map(([position, candidates]) => (
            <div key={position} style={{ marginBottom: 25 }}>
              <h3
                style={{
                  borderBottom: `2px solid ${theme.border}`,
                  paddingBottom: 4,
                }}
              >
                {position}
              </h3>

              {candidates.map((c) => (
                <div
                  key={c._id}
                  style={{
                    display: "flex",
                    gap: 15,
                    border: `2px solid ${theme.border}`,
                    padding: 15,
                    marginBottom: 12,
                    borderRadius: 10,
                    backgroundColor: theme.card,
                    alignItems: "flex-start",
                    boxShadow: darkMode
                      ? "0 2px 6px rgba(0,0,0,0.7)"
                      : "0 2px 6px rgba(0,0,0,0.2)",
                    transition: "transform 0.2s",
                  }}
                  onMouseEnter={(e) =>
                    (e.currentTarget.style.transform = "scale(1.02)")
                  }
                  onMouseLeave={(e) =>
                    (e.currentTarget.style.transform = "scale(1)")
                  }
                >
                  {/* Candidate Image */}
                  {c.image && (
                    <img
                      src={`${API_URL}/uploads/${c.image}`}
                      alt="candidate"
                      width="120"
                      style={{ borderRadius: 8, objectFit: "cover" }}
                    />
                  )}

                  {/* Candidate Details */}
                  <div style={{ flex: 1 }}>
                    <h3 style={{ margin: "0 0 5px 0" }}>
                      {c.firstName} {c.lastName}
                    </h3>
                    <p style={{ margin: "0 0 5px 0" }}>
                      <strong>Position:</strong> {c.candidacy}
                    </p>
                    <p style={{ margin: "0 0 8px 0" }}>{c.description}</p>
                    <p style={{ margin: 0 }}>
                      <strong>Votes:</strong> {c.votes || 0}
                    </p>

                    {/* User Voting */}
                    {auth.token && auth.role === "user" && (
                      <button
                        onClick={() => handleVote(c._id)}
                        style={{
                          backgroundColor: theme.button,
                          color: "white",
                          border: "none",
                          padding: "6px 12px",
                          borderRadius: 6,
                          cursor: "pointer",
                          marginTop: 8,
                        }}
                      >
                        Vote
                      </button>
                    )}

                    {/* Admin Actions */}
                    {auth.token && auth.role === "admin" && (
                      <div style={{ marginTop: 10 }}>
                        <button
                          onClick={() => {
                            setEditId(c._id);
                            setCandidateForm({
                              firstName: c.firstName,
                              lastName: c.lastName,
                              candidacy: c.candidacy,
                              description: c.description || "",
                              image: null,
                            });
                          }}
                          style={{
                            backgroundColor: "#16a34a",
                            color: "white",
                            border: "none",
                            padding: "6px 12px",
                            borderRadius: 6,
                            cursor: "pointer",
                            marginRight: 8,
                          }}
                        >
                          Edit
                        </button>

                        <button
                          onClick={() => handleDeleteCandidate(c._id)}
                          style={{
                            backgroundColor: "#dc2626",
                            color: "white",
                            border: "none",
                            padding: "6px 12px",
                            borderRadius: 6,
                            cursor: "pointer",
                          }}
                        >
                          Delete
                        </button>
                      </div>
                    )}
                  </div>
                </div>
              ))}
            </div>
          ))
        )}
      </section>
    </div>
  );
}

export default App;
